def base64decode(s):
    if isinstance(s, string_types):
        s = s.encode("utf-8")

    decoded = base64.urlsafe_b64decode(s.ljust(len(s) + len(s) % 4, b"="))
    try:
        decoded = decoded.decode("utf-8")
    except UnicodeDecodeError:
        pass
    return decoded

